$$\begin{array}{l}
  {\Delta y = f\left( x + \Delta x \right) - f(x) = f(2.01) - f(2)} \\
  {\phantom{\Delta y} = (2.01)^{3} - 2^{3} = 8.120601 - 8 = 0.120601}
  \end{array}$$

$$\begin{array}{l}
  {\Delta y = f\left( x + \Delta x \right) - f(x) = f(1.98) - f(2)} \\
  {\phantom{\Delta y} = (1.98)^{3} - 2^{3} = 7.762392 - 8 = - 0.237608}
  \end{array}$$

$$\begin{array}{l}
  {\Delta y \approx dy = f^{\prime}(x)\Delta x} \\
  {\phantom{\Delta y \approx dy} = \left( \left. \frac{1}{2\sqrt{x}} \right|_{x = 25} \right) \cdot (1.5) = \left( \frac{1}{10} \right)(1.5) = 0.15}
  \end{array}$$

$$\begin{array}{l}
  {\pi R^{2} - \pi r^{2} = f(R) - f(r)} \\
  {\phantom{\pi R^{2} - \pi r^{2}} = \Delta A\qquad\begin{array}{l}
  {\text{Remember,}\Delta A = \text{change in}f\text{when}x} \\
  {\text{changes from}x = r\text{to}x = R\text{.}}
  \end{array}} \\
  {\phantom{\pi R^{2} - \pi r^{2}} \approx dA} \\
  {\phantom{\pi R^{2} - \pi r^{2}} = f^{\prime}(r)dr}
  \end{array}$$
